import{_ as e}from"./chunks/files.B17OUyrr.js";import{_ as t,c as r,o as i,a2 as o}from"./chunks/framework.CIiVzG-O.js";const f=JSON.parse('{"title":"比較檔案","description":"並排打開兩份檔案，看顏色、跳改動，順手編輯或分享。","frontmatter":{"title":"比較檔案","description":"並排打開兩份檔案，看顏色、跳改動，順手編輯或分享。"},"headers":[],"relativePath":"zh-TW/guide/files.md","filePath":"zh-TW/guide/files.md","lastUpdated":1793948370000}'),l={name:"zh-TW/guide/files.md"};function s(n,a,d,h,c,p){return i(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="比較檔案" tabindex="-1">比較檔案 <a class="header-anchor" href="#比較檔案" aria-label="Permalink to &quot;比較檔案&quot;">​</a></h1><p>大多數人都是從這裡開始的：同一份檔案的兩個版本並排放好，不同的地方全部標出來。</p><img src="'+e+'" alt="兩份文字檔案並排比較，改動帶有顏色" class="guide-shot"><h2 id="打開兩份檔案" tabindex="-1">打開兩份檔案 <a class="header-anchor" href="#打開兩份檔案" aria-label="Permalink to &quot;打開兩份檔案&quot;">​</a></h2><p>用選單「檔案 → 開啟」，或者直接把兩個檔案拖進 qDiff 視窗。要對照三個版本？ 再加一欄就好，顏色規則一樣。最近比過的內容會留在歡迎頁，下次一點就回來。</p><h2 id="顏色是什麼意思" tabindex="-1">顏色是什麼意思 <a class="header-anchor" href="#顏色是什麼意思" aria-label="Permalink to &quot;顏色是什麼意思&quot;">​</a></h2><ul><li><strong>淡紅</strong> —— 這一側的內容被刪掉了，或者屬於舊版本。</li><li><strong>淡綠</strong> —— 這一側是新增的，或者屬於新版本。</li><li><strong>行裡更深的一小塊</strong> —— 具體改動的那幾個字。哪怕一行只改了一個字， 也不會被整行顏色蓋住。</li></ul><p>兩側會同步捲動，永遠停在同一行上。</p><h2 id="在改動之間跳轉" tabindex="-1">在改動之間跳轉 <a class="header-anchor" href="#在改動之間跳轉" aria-label="Permalink to &quot;在改動之間跳轉&quot;">​</a></h2><p>點文字旁邊那條細長的小地圖，可以跳到檔案任意位置；也可以用「上一處 / 下一處」 按鈕（有快捷鍵）逐個查看。檔案很長時，小地圖還能告訴你目前看到哪裡了。</p><h2 id="邊看邊改" tabindex="-1">邊看邊改 <a class="header-anchor" href="#邊看邊改" aria-label="Permalink to &quot;邊看邊改&quot;">​</a></h2><p>兩側都能直接編輯、復原。每一處改動都可以單獨複製過去、替換或刪除 —— 在比較 介面裡就能做完，不用再打開別的編輯器。改完照常儲存即可。</p><div class="tip custom-block"><p class="custom-block-title">分享成圖片</p><p>選中一處改動，可以把它匯出成一張乾淨的雙欄圖片，貼到聊天或審查裡很方便， 匯出的圖片不帶任何標記。</p></div><p>接下來：<a href="./folders.html">比較整個資料夾</a>。</p>',14)])])}const m=t(l,[["render",s]]);export{f as __pageData,m as default};
